import csv,html,json
from pathlib import Path
D=Path(__file__).parent;s=json.loads((D/'summary.json').read_text('utf8'));rep=json.loads((D/'reappearance.json').read_text('utf8'))
a={m:s[m]['sensitivity_article_like'] for m in ['文心','百度']}
lines=['# GEO 文心、百度近15天：文章字数与被引用情况','',f"统计窗口：{s['window']['window_start']}—{s['window']['window_end']}（北京时间，含今天未结束的数据）。数据快照：{s['window']['as_of']}。",'', '**结论：未发现可靠证据表明，单独增加文章字数就能提高被推荐概率。** 文心只有很弱的正相关；百度把百科等页面与普通文章混在一起时看似有正相关，排除这些页面后，相关性基本为零。','', '## 样本与统计口径','', '- 只使用主 GEO 的文心、百度采集记录，不混入内容创作专用补采。','- 窗口内共有 4,144 次独立采集记录，覆盖 21 个监测问题；其中 4,001 次来源列表完整。来源不完整记录不进入主分析。','- 同一 task_id 去重；同一次答复中同一规范化 URL 只计一次引用。独立搜索得到相同答复仍保留，另做剔除相同答复的敏感性检查。','- 完整来源列表共涉及 7,378 个跨平台去重 URL。6,116 个具有可读缓存正文；进一步剔除低质量和清洗后有效字符不足 80 的正文，主可读样本为 5,879 个 URL（79.7%）。同一 URL 在两平台各计一次平台样本。','- 文章口径再剔除 baike.baidu.com、baidu.com、zhidao.baidu.com 域名页面，作为百科、搜索或问答混入的保守敏感性分析。其他网址仍可能存在页面类型误分，结果属于近似文章样本。','- 字数指已提取正文中的汉字、英文字母、数字字符总数，不计空白和标点；另提供纯汉字数和非空白字符数。使用生产正文截尾清洗规则；部分中等质量正文仍可能带有标题、作者、少量导航，非逐篇人工审核字数。','- 使用现存正文快照，不重新抓取。正文抓取时间可能与推荐时间不同，不能排除页面后续改版。','', '## 普通文章口径的字数分布','', '| 项目 | 文心 | 百度 |','|---|---:|---:|',f"| 有效 URL 样本 | {a['文心']['valid_articles']:,} | {a['百度']['valid_articles']:,} |",f"| 字数中位数 | {a['文心']['median']:,.0f} | {a['百度']['median']:,.0f} |",f"| 中间50%的字数范围 | {a['文心']['p25']:,.0f}—{a['文心']['p75']:,.0f} | {a['百度']['p25']:,.0f}—{a['百度']['p75']:,.0f} |",'', '| 字数区间 | 文心文章数（占比） | 百度文章数（占比） |','|---|---:|---:|']
for x,y in zip(a['文心']['bins'],a['百度']['bins']):lines.append(f"| {x['bin']} | {x['unique_articles']:,}（{x['article_share']:.1%}） | {y['unique_articles']:,}（{y['article_share']:.1%}） |")
lines += ['', '两平台样本最多的区间均为 3,000—4,999 字。这个分布是“已经入选的文章长什么样”，不能解释成该区间有相同比例的入选概率。','', '## 字数是否与重复引用有关','', '| 分析方式 | 文心 | 百度 |','|---|---:|---:|',f"| 混合所有可读页面：字数与引用次数的 Spearman 相关 | {s['文心']['association']['spearman']:.3f} | {s['百度']['association']['spearman']:.3f} |",f"| 剔除百科等页面后：Spearman 相关 | {a['文心']['association']['spearman']:.3f} | {a['百度']['association']['spearman']:.3f} |",f"| 同网站、同问题组内比较：对数字数与 log(1+引用次数)相关 | {a['文心']['adjusted']['within_domain_question_log_correlation']:.3f} | {a['百度']['adjusted']['within_domain_question_log_correlation']:.3f} |",f"| 按相同正文哈希合并 URL：Spearman 相关 | {s['文心']['sensitivity_content_dedup']['spearman']:.3f} | {s['百度']['sensitivity_content_dedup']['spearman']:.3f} |",'','- 文心普通文章相关系数约 0.067，效应很弱，不能据此认为加长文章有明显收益。','- 百度混合页面相关系数约 0.401，排除百科等页面后降至约 0.004。同网站同问题内也没有明显正相关；原先的表面趋势与网站及页面类型构成相伴。','- 普通文章同网站同问题分组只保留每组至少 5 篇、字数和引用次数均有变化的分组；文心 4,276 篇、119 组，百度 363 篇、21 组。它只减少这两类混杂，不能控制全部影响因素。','- 百度普通文章各长度组平均引用约为：不足1,000字 10.50 次（仅2篇）、1,000—1,999字 7.54 次（13篇）、2,000—2,999字 11.13 次、3,000—4,999字 11.61 次、5,000—7,999字 12.91 次、8,000字以上 11.37 次。没有稳定的“越长越多”关系，短文组样本很少。','', '## 对时间暴露差异的额外检查','', '重复引用次数也受文章进入样本的早晚影响。额外统计“首次出现日期之后，在相同问题的完整来源采集中再次出现的比例”：分子是后续引用次数，分母是后续相同问题的采集次数。这里只能衡量已入选文章的后续再入选情况，不是所有文章的入选概率。','',f"- 全部可读页面：文心后续再入选率与字数秩相关 {rep['文心']['association']['spearman']:.3f}；百度 {rep['百度']['association']['spearman']:.3f}。",f"- 同网站同问题组内，对数字数与 log(1+后续再入选率)相关：文心 {rep['文心']['adjusted']['within_domain_question_log_correlation']:.3f}；百度 {rep['百度']['adjusted']['within_domain_question_log_correlation']:.3f}。结论仍是文心很弱、百度组内没有明显正相关。",'- 剔除今天未结束数据后，全部可读页面的秩相关为文心 0.067、百度 0.430，页面类型混杂依然存在。','', '## 对创作策略的含义','', '**可以把 3,000—5,000 字作为下一轮受控测试的常见长度档，但本次不能证明它是最优长度。** 当前证据不支持仅为提高引用率就把所有文章统一加长到 8,000 字。保留内容质量，根据问题所需信息组织篇幅。','', '若要回答“多写多少字能提高多少推荐概率”，需要把未被引用的已发布文章也加入样本。建议在相同平台、相近发布时间、同一产品问题和相同监测频次下，对 1,500—2,500、3,000—4,500、5,000—6,500 字三个档做文章级随机分配；每档记录全部发布 URL，包括零引用文章，并至少跟踪固定 14 天。测试方案尚未执行，也未修改创作配置。','', '## 解释边界','', '- 这里只观察到了被引用的 URL，缺少全部发布/收录文章及曝光机会总数，无法计算总体入选概率；存在幸存者偏差。','- 引用发生在答复的信源列表，不等同于平台推荐某品牌或产品；也不包含已验证的位置权重。','- 原文缓存覆盖、网站可访问性、正文抽取质量都会影响样本；失败/缺失正文没有作为零字纳入。','- 问题、网站权重、内容类型、发布时间、收录情况、排名、产品和文章质量都可能与字数同时变化。不能将相关当作因果。','- 重复引用和转载导致样本之间不完全独立。脚本中的置换检验及文章级近似自助区间仅作探索，不能当成严格的独立实验显著性结论。','', '## 文件','', '- `文章字数与推荐明细.csv`：按平台、URL列出字数、引用次数、首次/末次出现、质量和抓取时间。','- `普通文章字数区间.csv`：剔除百科等页面后的区间汇总。','- `字数区间统计.csv`：全部合格可读页面的区间汇总。','- `文心后续再入选率.csv`、`百度后续再入选率.csv`：已入选文章的后续观察明细。','- `summary.json`、`reappearance.json`、`dataset.json` 及 Python 脚本：可复核的汇总、分析副本和统计过程。']
(D/'分析报告.md').write_text('\n'.join(lines)+'\n',encoding='utf8')
with (D/'普通文章字数区间.csv').open('w',encoding='utf-8-sig',newline='') as f:
 w=csv.DictWriter(f,fieldnames=['platform',*a['文心']['bins'][0]]);w.writeheader()
 for m in a:
  for b in a[m]['bins']:w.writerow(dict(platform=m,**b))
# Standalone exportable SVG chart.
svg=['<svg xmlns="http://www.w3.org/2000/svg" width="1100" height="570" viewBox="0 0 1100 570"><rect width="1100" height="570" fill="#f7fafc"/><g font-family="Microsoft YaHei, sans-serif" fill="#183346">','<text x="45" y="49" font-size="25" font-weight="700">被引用文章的字数分布</text>','<text x="45" y="79" font-size="14">2026-10-16—10-30 · 剔除百科等页面 · 图中比例是样本分布，不是被推荐概率</text>']
for i,(x,y) in enumerate(zip(a['文心']['bins'],a['百度']['bins'])):
 yy=127+i*58;svg.append(f'<text x="45" y="{yy+17}" font-size="15">{x["bin"]}</text>')
 for j,(v,color) in enumerate([(x,'#158f83'),(y,'#d18237')]):
  py=yy+j*22;ww=v['article_share']*1050
  svg.append(f'<rect x="185" y="{py}" width="{ww:.1f}" height="17" rx="3" fill="{color}"/><text x="{195+ww:.1f}" y="{py+14}" font-size="13">{v["article_share"]:.1%} · {v["unique_articles"]:,}篇</text>')
svg+=['<rect x="45" y="502" width="15" height="15" fill="#158f83"/><text x="69" y="515" font-size="14">文心 5,425篇 · 字数中位数3,191</text>','<rect x="450" y="502" width="15" height="15" fill="#d18237"/><text x="474" y="515" font-size="14">百度 448篇 · 字数中位数3,969</text>','<text x="45" y="549" font-size="12" fill="#5c6e7a">字数口径：正文汉字、英文字母和数字字符数；不计空白和标点。现有缓存正文，非逐篇人工审核。</text></g></svg>']
(D/'字数分布.svg').write_text(''.join(svg),encoding='utf8')
# Small self-contained interactive report; no external requests.
content='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>GEO 文章字数分析</title><style>body{font:16px/1.7 "Microsoft YaHei",sans-serif;background:#f4f7fa;color:#203745;margin:0}main{max-width:1050px;margin:auto;padding:30px}h1{font-size:29px}section{background:white;border:1px solid #dbe4e9;border-radius:14px;padding:24px;margin:20px 0}select{font:inherit;padding:8px}table{border-collapse:collapse;width:100%;font-size:14px}td,th{padding:10px;text-align:left;border-bottom:1px solid #e5ebef}.muted{color:#607482}.key{font-size:20px;color:#087a70}svg{width:100%;height:auto}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}@media(max-width:650px){main{padding:14px}.grid{display:block}}</style><main><h1>字数越长，会更容易被 GEO 引用吗？</h1><p class="muted">2026-10-16—10-30 · 主 GEO 文心与百度 · 今天为部分数据</p><section><p class="key">现有数据未证明单独增加字数能提高推荐概率。</p><p>文心只有很弱的正相关。百度的表面正相关，在剔除百科等页面、或限定同网站同问题后基本消失。</p></section><section>'''
content+=''.join(svg)+'</section><section><label>查看口径：<select id="scope"><option value="article">剔除百科等页面</option><option value="all">全部合格可读信源页面</option></select></label><div id="metrics" class="grid"></div><table><thead><tr><th>字数区间</th><th>文心：文章数/平均引用</th><th>百度：文章数/平均引用</th></tr></thead><tbody id="table"></tbody></table><p class="muted">平均引用次数受首次出现时间、监测频次及网站类型影响，不能当作总体推荐概率。</p></section><section><h2>这份结果能告诉你什么</h2><p>3,000—4,999字是当前被引用文章最常见的长度区间，可以作为后续对照测试的一档；它不是已证实的最佳长度。</p><p>统计仅包含被引用页面，缺少未被引用文章这个分母。样本覆盖存在缺失，正文抽取可能有少量页面元素残留。</p><p>正式验证需要将全部发布URL（包括零引用文章）纳入，并在相同问题、网站、发布时间和观察天数下比较不同长度。</p><p>分析副本、逐链接CSV和详细方法见同目录文件。</p></section></main><script>'
content+='const data='+json.dumps(s,ensure_ascii=False)+';function render(){let art=document.querySelector("#scope").value==="article";let w=art?data["文心"].sensitivity_article_like:data["文心"],b=art?data["百度"].sensitivity_article_like:data["百度"];document.querySelector("#metrics").innerHTML=[["文心",w],["百度",b]].map(([n,v])=>`<p><b>${n}</b> · ${v.valid_articles.toLocaleString()}篇<br>中位数 ${Math.round(v.median).toLocaleString()}字<br>字数与引用次数相关 ${v.association.spearman.toFixed(3)}</p>`).join("");document.querySelector("#table").innerHTML=w.bins.map((x,i)=>`<tr><td>${x.bin}</td><td>${x.unique_articles.toLocaleString()}篇 / ${x.mean_recommendations.toFixed(2)}次</td><td>${b.bins[i].unique_articles.toLocaleString()}篇 / ${b.bins[i].mean_recommendations.toFixed(2)}次</td></tr>`).join("")}document.querySelector("#scope").onchange=render;render();</script>'
(D/'分析报告.html').write_text(content,encoding='utf8')
print('Reports created. Snapshot',s['window']['as_of'])
